# New in Nov 2026: Documents screen (sort / filters / pills / limit), History screen (days, filters, paging, tap-through),
# DEMO mode (header badge, data, reset, exit, isolation from a signed-in test user) and Back-button navigation. Test build on :8765.
import asyncio
from playwright.async_api import async_playwright
BASE='http://127.0.0.1:8765/index.html'
res=[]
def ok(n,c,x=''):
    c=bool(c);res.append(c);print(('PASS ' if c else 'FAIL ')+n+('' if c else f' — {x}'))
titles=lambda pg,sel='#v1 .dl:not([hidden]) b': pg.eval_on_selector_all(sel,'e=>e.map(x=>x.textContent)')
async def main():
    async with async_playwright() as p:
        b=await p.chromium.launch()
        ctx=await b.new_context(viewport={'width':390,'height':844},device_scale_factor=2,locale='th-TH',has_touch=True,is_mobile=True,accept_downloads=True)
        pg=await ctx.new_page(); errs=[]
        pg.on('console',lambda m: errs.append(m.text) if m.type in('error','warning') else None); pg.on('pageerror',lambda e: errs.append('pageerror '+str(e)))
        await pg.goto('about:blank'); await pg.goto(BASE+'?demo'); await pg.wait_for_selector('#v0.on .pimg.ok',timeout=60000); await pg.wait_for_timeout(500)
        # ---------------- DEMO mode
        ok('no DEMO badge left in the header and no yellow strip', await pg.locator('#hdr .badge.dm').count()==0 and await pg.locator('#demob').count()==0)
        ok('header starts at the very top (nothing added above it)', await pg.evaluate("document.querySelector('#hdr').getBoundingClientRect().top")==0)
        ok('Home has exactly one DEMO label: the "DEMO VERSION" strip', await pg.locator('#v0 .dstrip').count()==1 and (await pg.inner_text('#v0 .dstrip')).strip()=='DEMO VERSION' and await pg.locator('#v0 .demo').count()==0 and (await pg.inner_text('#v0')).count('DEMO')==1, await pg.inner_text('#v0 .dstrip'))
        ok('strip comes right after the announcements and outside every announcement card', await pg.evaluate("(()=>{const s=document.querySelector('#v0 .dstrip'),l=document.querySelector('#v0 .nl');return !s.closest('.nc')&&!s.closest('.nl')&&l.nextElementSibling===s&&s.getBoundingClientRect().top>=l.getBoundingClientRect().bottom-1})()"))
        sd=await pg.evaluate("(()=>{const s=document.querySelector('#v0 .dstrip'),c=getComputedStyle(s),r=s.getBoundingClientRect();return {bg:c.backgroundColor,fg:c.color,ta:c.textAlign,h:r.height,w:r.width,iw:innerWidth}})()")
        ok('strip is a full-width navy bar with white centred text and moderate height', sd['bg']=='rgb(26, 32, 88)' and sd['fg']=='rgb(255, 255, 255)' and sd['ta']=='center' and 30<=sd['h']<=44 and abs(sd['w']-sd['iw'])<=1, sd)
        ok('home shows the demo document and the announcements', await pg.locator('#v0 .face:not(.bk) .pimg.ok').count()==1 and await pg.locator('#v0 .nc').count()==6)
        await pg.click('#nv > :nth-child(2)'); await pg.wait_for_selector('#v1 .dl'); await pg.click('#v1 .dl >> nth=0'); await pg.wait_for_selector('#sh.on'); await pg.click('#sh [data-act=det-open]'); await pg.wait_for_selector('#dp.on .pf-body'); await pg.wait_for_timeout(500)
        ok('details page opens full screen', await pg.eval_on_selector('#dp','e=>e.getBoundingClientRect().top')==0)
        ok('document details (notes) still open from the Documents sheet and show fictional data', 'SAMPLE-0001' in await pg.inner_text('#dp'))
        await pg.click('#dp [data-act=det-close]'); await pg.wait_for_timeout(500); await pg.click('#nv > :nth-child(1)'); await pg.wait_for_timeout(400)
        for i,n in [(2,'#v1'),(4,'#v3'),(5,'#v4'),(3,'#v2')]:
            await pg.click(f'#nv > :nth-child({i})'); await pg.wait_for_timeout(300)
            ok(f'tab {i}: DEMO stated in its footer' if i in(2,3,4,5) else f'tab {i}', i not in(2,3,4,5) or 'DEMO' in await pg.inner_text(f'#v{i-1} .dfoot'))
        await pg.click('#nv > :nth-child(5)'); await pg.wait_for_timeout(400)
        st=await pg.inner_text('#v4')
        ok('Settings (demo): demo card with reset/exit, no sign-out or delete-account rows', 'ออกจากโหมด DEMO' in st and 'รีเซ็ตข้อมูลตัวอย่าง' in st and 'ลบบัญชีและข้อมูลทั้งหมด' not in st and await pg.locator('#v4 [data-act=logout-ask]').count()==0)
        ok('Settings keeps profile, watermark, lock, banners sections', all(k in st for k in ['แก้ไขข้อมูลบัตร','รูปโปรไฟล์','ลายน้ำ','ล็อกแอปด้วยรหัส','หน้าหลัก: แบนเนอร์และประกาศ']))
        await pg.click('#nv > :nth-child(3)'); await pg.wait_for_timeout(300)
        ok('Scan screen warns that demo uploads stay in memory', 'หน่วยความจำ' in await pg.inner_text('#v2'))
        await pg.click('#nv > :nth-child(5)'); await pg.wait_for_timeout(300); await pg.click('#v4 [data-act=demo-menu]'); await pg.wait_for_selector('#sh.on')
        ok('DEMO menu lists 5 presentation steps + reset + exit', await pg.locator('#sh [data-act=demo-step]').count()==5 and await pg.locator('#sh [data-act=demo-reset]').count()==1 and await pg.locator('#sh [data-act=demo-exit]').count()==1)
        await pg.click('#sh [data-act=demo-step][data-i="3"]'); await pg.wait_for_timeout(400)
        ok('presentation step jumps to History', await pg.locator('#v3.on').count()==1 and await pg.locator('#sh.on').count()==0)
        # ---------------- Documents
        await pg.click('#nv > :nth-child(2)'); await pg.wait_for_selector('#v1.on .dl'); await pg.wait_for_selector('#v1 .th img.ok'); await pg.wait_for_timeout(300)
        ok('Documents: 6 demo documents, header 6/20, count line', await pg.locator('#v1 .dl').count()==6 and '6/20' in await pg.inner_text('#v1 .mh') and '6 รายการ' in await pg.inner_text('#dcount'))
        ok('category chips carry counts', 'บัตร / ใบอนุญาต 1' in (await pg.inner_text('#dcat')).replace('\n',' ') and 'ทั้งหมด 6' in (await pg.inner_text('#dcat')).replace('\n',' '))
        t=await titles(pg); ok('default sort = newest first', t[0]=='ใบอนุญาตตัวอย่าง' and t[-1]=='ประกันสุขภาพตัวอย่าง', t)
        th=await pg.eval_on_selector('#v1 .dl .th','e=>[e.getBoundingClientRect().width,e.getBoundingClientRect().height]'); ok('thumbnail keeps its 72x54 size (not stretched)', abs(th[0]-72)<1 and abs(th[1]-54)<1, th)
        await pg.select_option('#dsort','name'); await pg.wait_for_timeout(200); t=await titles(pg); exp=await pg.evaluate("t=>[...t].sort((a,b)=>a.localeCompare(b,'th'))",t); ok('sort by name (Thai collation)', t==exp, t)
        await pg.select_option('#dsort','exp'); await pg.wait_for_timeout(200); t=await titles(pg); ok('sort by expiry: expired first, then soonest, no-expiry last', t[0]=='ประกันสุขภาพตัวอย่าง' and t[1]=='ใบอนุญาตตัวอย่าง' and t[-1] in('ใบเสร็จค่าไฟตัวอย่าง','ใบรับรองการศึกษาตัวอย่าง'), t)
        ok('sort choice is remembered on this device', await pg.evaluate("localStorage.getItem('dp_dsort')")=='"exp"')
        await pg.select_option('#dsort','new'); await pg.wait_for_selector('#v1 .th img.ok'); await pg.wait_for_timeout(300)
        ok('thumbnails still load after re-sorting', await pg.locator('#v1 .th img.ok').count()==6)
        rows=await pg.eval_on_selector_all('#v1 .dl','e=>e.map(x=>x.innerText.replace(/\\n/g," "))')
        ok('expired / soon / ok pills', any('ประกันสุขภาพตัวอย่าง' in r and 'หมดอายุแล้ว' in r for r in rows) and any('ใบอนุญาตตัวอย่าง' in r and 'หมดอายุในอีก 28 วัน' in r for r in rows) and any('ทะเบียนรถ' in r and 'ใช้ได้ถึง' in r for r in rows), rows)
        ok('front/back status kept on each row', any('สัญญาเช่าตัวอย่าง' in r and 'หลัง –' in r for r in rows) and any('ใบอนุญาตตัวอย่าง' in r and 'หน้า ✓ · หลัง ✓' in r for r in rows))
        for v,n in [('soon',1),('expired',1),('incomplete',3),('all',6)]:
            await pg.click(f'#dst [data-v={v}]'); await pg.wait_for_timeout(120); ok(f'status filter {v} -> {n} documents', await pg.locator('#v1 .dl:not([hidden])').count()==n, await pg.locator('#v1 .dl:not([hidden])').count())
        await pg.click('#dst [data-v=incomplete]'); ok('count line explains the filter', 'แสดง 3 จาก 6' in await pg.inner_text('#dcount'))
        await pg.click('#dcat [data-c="สัญญา"]'); await pg.wait_for_timeout(120); ok('category + status combine (สัญญา & ภาพไม่ครบ = 1)', await pg.locator('#v1 .dl:not([hidden])').count()==1)
        await pg.click('#dcat [data-c="สุขภาพ"]'); await pg.wait_for_timeout(120); ok('no match shows message and a clear button', await pg.locator('#dnone').count()==1 and await pg.locator('#dlist:visible').count()==0)
        await pg.click('#dnone [data-act=doc-clear]'); await pg.wait_for_timeout(200); ok('clear restores all 6 and empties search', await pg.locator('#v1 .dl:not([hidden])').count()==6 and await pg.input_value('#dq')=='' and await pg.locator('#dnone').count()==0)
        await pg.fill('#dq','sample-0005'); await pg.wait_for_timeout(150); ok('search by document number (case-insensitive)', await titles(pg)==['ทะเบียนรถตัวอย่าง'])
        await pg.fill('#dq','ซzzz'); await pg.wait_for_timeout(150); ok('search with no result -> message', await pg.locator('#dnone').count()==1)
        await pg.fill('#dq',''); await pg.wait_for_timeout(150)
        await pg.click('#v1 .dl >> nth=1'); await pg.wait_for_selector('#sh.on .slot'); ok('tap row opens manage sheet', await pg.locator('#sh [data-act=doc-show]').count()==1)
        name=await pg.input_value('#rt'); await pg.click('#sh [data-act=doc-show]'); await pg.wait_for_selector('#v0.on .pimg'); await pg.wait_for_timeout(400)
        ok('"แสดงบนหน้าหลัก" puts that document on Home', name in (await pg.get_attribute('#v0 .face:not(.bk) .pimg','alt') or ''), name)
        # ---------------- History
        await pg.click('#nv > :nth-child(4)'); await pg.wait_for_selector('#v3.on .hr'); await pg.wait_for_timeout(300)
        heads=await pg.eval_on_selector_all('#v3 .hd3','e=>e.map(x=>x.textContent)')
        ok('History groups by day: วันนี้ / เมื่อวาน / dated headings', 'วันนี้' in heads and 'เมื่อวาน' in heads and len(heads)>=4, heads)
        ok('first page shows 25 rows + "show more"', await pg.locator('#v3 .hr').count()==25 and await pg.locator('#v3 [data-act=hist-more]').count()==1)
        for k in ['เข้าสู่ระบบ','อัปโหลดเอกสาร','เปิดดูเอกสาร','บันทึกสำเนาลายน้ำ','เปลี่ยนภาพเอกสาร','อัปเดตโปรไฟล์']: ok('History has label '+k, k in await pg.inner_text('#v3'))
        await pg.click('#v3 [data-act=hist-more]'); await pg.wait_for_timeout(250); n=await pg.locator('#v3 .hr').count(); ok('show more loads the rest, button disappears', n>25 and await pg.locator('#v3 [data-act=hist-more]').count()==0, n)
        fc=await pg.eval_on_selector_all('#hf button','e=>e.map(x=>[x.dataset.v,+x.querySelector("em").textContent])'); d=dict(fc)
        ok('filter chip counts add up', d['up']+d['view']+d['copy']+d['del']+d['acct']==d['all'], d)
        await pg.click('#hf [data-v=view]'); await pg.wait_for_timeout(200); kinds=await pg.eval_on_selector_all('#v3 .hr b','e=>[...new Set(e.map(x=>x.textContent))]'); ok('filter "เปิดดู" shows only view rows', kinds==['เปิดดูเอกสาร'], kinds)
        await pg.click('#hf [data-v=del]'); await pg.wait_for_timeout(200); ok('filter "ลบ" shows the deleted row, which is not a link', await pg.locator('#v3 .hr').count()==1 and await pg.locator('#v3 button.hr').count()==0)
        await pg.click('#hf [data-v=all]'); await pg.wait_for_timeout(200)
        await pg.click('#v3 button.hr >> nth=0'); await pg.wait_for_selector('#sh.on .slot'); ok('tapping a history row opens its document', await pg.locator('#sh [data-act=det-open]').count()==1)
        await pg.keyboard.press('Escape'); await pg.wait_for_timeout(350)
        # opening a document adds a new history row
        n0=int((await pg.inner_text('#v3 .mh small')).split()[0])
        await pg.click('#nv > :nth-child(1)'); await pg.wait_for_selector('#v0.on .pimg.ok'); await pg.click('#v0 [data-act=open-view]'); await pg.wait_for_selector('#vwr.on'); await pg.wait_for_timeout(700); await pg.click('#vwr [data-act=view-close]'); await pg.wait_for_timeout(700)
        await pg.click('#nv > :nth-child(4)'); await pg.wait_for_timeout(300); n1=int((await pg.inner_text('#v3 .mh small')).split()[0]); ok('viewing a document adds a history row', n1==n0+1, (n0,n1))
        # ---------------- Back button (Android / browser back)
        await pg.click('#nv > :nth-child(2)'); await pg.click('#v1 .dl >> nth=0'); await pg.wait_for_selector('#sh.on'); await pg.go_back(); await pg.wait_for_timeout(400)
        ok('Back closes the open sheet and stays on the tab', await pg.locator('#sh.on').count()==0 and await pg.locator('#v1.on').count()==1)
        await pg.go_back(); await pg.wait_for_timeout(400); ok('Back from another tab returns to Home', await pg.locator('#v0.on').count()==1 and 'about:blank' not in pg.url and '?demo' in pg.url)
        await pg.click('#v0 [data-act=prof-open]'); await pg.wait_for_selector('#pi.on'); await pg.wait_for_timeout(300); await pg.go_back(); await pg.wait_for_timeout(500); ok('Back closes the ข้อมูลบัตร screen', await pg.locator('#pi.on').count()==0 and await pg.locator('#v0.on').count()==1)
        await pg.click('#v0 [data-act=open-view]'); await pg.wait_for_selector('#vwr.on'); await pg.wait_for_timeout(600); await pg.go_back(); await pg.wait_for_timeout(900); ok('Back closes the expanded card view', await pg.locator('#vwr.on').count()==0)
        await pg.go_back(); await pg.wait_for_timeout(600); ok('Back at Home with nothing open leaves the app', pg.url=='about:blank', pg.url)
        await pg.goto(BASE+'?demo'); await pg.wait_for_selector('#v0.on .pimg.ok',timeout=60000)
        # ---------------- Reset
        await pg.click('#nv > :nth-child(3)'); await pg.fill('#st','เอกสารทดลอง'); await pg.set_input_files('#fg','fixtures/front.jpg'); await pg.wait_for_selector('.pv-img'); await pg.click('[data-act=scan-save]'); await pg.wait_for_selector('#v0.on .pimg.ok'); await pg.wait_for_timeout(500)
        await pg.click('#nv > :nth-child(2)'); await pg.wait_for_selector('#v1 .dl'); ok('upload inside DEMO works (7 documents)', await pg.locator('#v1 .dl').count()==7)
        await pg.click('#nv > :nth-child(5)'); await pg.wait_for_timeout(300); await pg.click('#v4 [data-act=demo-reset]'); await pg.wait_for_selector('#v0.on .pimg.ok',timeout=60000); await pg.wait_for_timeout(500)
        await pg.click('#nv > :nth-child(2)'); await pg.wait_for_selector('#v1 .dl'); ok('Reset removes the added document and restores 6 samples', await pg.locator('#v1 .dl').count()==6 and 'เอกสารทดลอง' not in await pg.inner_text('#v1'))
        # ---------------- Limit of 20 documents
        for i in range(14):
            await pg.click('#nv > :nth-child(3)'); await pg.wait_for_selector('#v2.on'); await pg.select_option('#sd','new'); await pg.fill('#st',f'เติม {i}'); await pg.set_input_files('#fg','fixtures/front.jpg'); await pg.wait_for_selector('.pv-img'); await pg.click('[data-act=scan-save]'); await pg.wait_for_selector('#v0.on .pimg.ok'); await pg.wait_for_timeout(150)
        await pg.click('#nv > :nth-child(2)'); await pg.wait_for_selector('#v1 .dl'); ok('at 20/20 the add buttons are disabled and a notice explains why', '20/20' in await pg.inner_text('#v1 .mh') and await pg.locator('#v1 .ffbtns button:disabled').count()==2 and 'ครบ 20' in await pg.inner_text('#v1'))
        ok('status chips show only existing groups', await pg.locator('#dst').count()==1)
        await b.close()
        # ---------------- Demo from the login screen + isolation from a signed-in test user
        b=await p.chromium.launch(); ctx=await b.new_context(viewport={'width':390,'height':844},locale='th-TH'); pg=await ctx.new_page()
        pg.on('pageerror',lambda e: errs.append('pageerror '+str(e)))
        await pg.goto(BASE+'?login'); await pg.wait_for_selector('#auth')
        ok('login screen offers the DEMO button', await pg.locator('#auth [data-act=demo-start]').count()==1 and 'ไม่ต้องสมัคร' in await pg.inner_text('#auth [data-act=demo-start]'))
        await pg.click('#auth [data-act=demo-start]'); await pg.wait_for_selector('#v0.on .pimg.ok',timeout=60000); ok('DEMO starts from the login screen', await pg.is_visible('#v0 .dstrip') and await pg.locator('#auth').count()==0)
        await pg.click('#nv > :nth-child(5)'); await pg.wait_for_timeout(300); await pg.click('#v4 [data-act=demo-exit]'); await pg.wait_for_function("!document.querySelector('#v0 .dstrip')||true",timeout=20000); await pg.wait_for_timeout(1500); await pg.wait_for_selector('#v0.on .pimg.ok',timeout=60000)
        ok('Exit reloads the app out of DEMO: no demo flag in the URL, the test user (not the presenter) is back', 'demo' not in pg.url.split('?')[-1] and 'presenter@docpocket.demo' not in await pg.evaluate("document.body.innerText"), pg.url)
        await b.close()
        b=await p.chromium.launch(); ctx=await b.new_context(viewport={'width':390,'height':844},locale='th-TH'); pg=await ctx.new_page()
        await pg.goto(BASE); await pg.wait_for_selector('#v0.on .pimg.ok',timeout=60000)   # test build signs in a normal (non-demo) test user
        ok('normal session (test user): the DEMO VERSION strip is shown because the test build is a demo', await pg.locator('#v0 .dstrip').count()==1)
        await pg.click('#nv > :nth-child(5)'); await pg.wait_for_timeout(300); ok('Settings offers "เปิดโหมด DEMO" for a signed-in user', await pg.locator('#v4 [data-act=demo-start]').count()==1 and await pg.locator('#v4 [data-act=logout-ask]').count()==1)
        mine=await pg.evaluate("document.querySelector('#v0') && 1"); await pg.click('#v4 [data-act=demo-start]'); await pg.wait_for_selector('#v0.on .pimg.ok',timeout=60000)
        await pg.click('#nv > :nth-child(2)'); await pg.wait_for_selector('#v1 .dl'); t=await titles(pg); ok('demo shows demo documents, not the signed-in user\'s', len(t)==6 and 'ทะเบียนรถตัวอย่าง' in t and 'ใบอนุญาตตัวอย่าง' in t, t)
        await b.close()
    bad=[e for e in errs if 'TUNNEL' not in e and 'fonts.googleapis' not in e and 'net::ERR' not in e]
    ok('no console errors or page errors', not bad, bad[:3])
    print(f'{sum(res)}/{len(res)} feature checks passed')
asyncio.run(main())
